package it.farmacidicasa;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import com.google.common.util.concurrent.ListenableFuture;import com.google.mlkit.vision.barcode.*;import com.google.mlkit.vision.common.InputImage;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
public class ScanActivity extends ComponentActivity {
 private PreviewView view;private ProcessCameraProvider provider;private BarcodeScanner scanner;private final ExecutorService executor=Executors.newSingleThreadExecutor();private final AtomicBoolean busy=new AtomicBoolean(false);private volatile boolean finished=false;private androidx.camera.core.Camera camera;private boolean torch=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff183730);root.setPadding(20,40,20,20);TextView title=new TextView(this);title.setText("Inquadra il codice a barre\nAvvicina il codice e mantieni ferma la confezione.\nCode 32 italiano / AIC: verifica sempre il risultato.");title.setTextColor(Color.WHITE);title.setTextSize(18);title.setPadding(0,10,0,20);root.addView(title);view=new PreviewView(this);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));Button light=new Button(this);light.setText("Accendi / spegni torcia");light.setOnClickListener(v->{if(camera!=null&&camera.getCameraInfo().hasFlashUnit()){torch=!torch;camera.getCameraControl().enableTorch(torch);}});root.addView(light);Button cancel=new Button(this);cancel.setText("Annulla scansione");cancel.setOnClickListener(v->finish());root.addView(cancel);setContentView(root);scanner=BarcodeScanning.getClient();if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)start();else requestPermissions(new String[]{Manifest.permission.CAMERA},1);}
 @Override public void onRequestPermissionsResult(int req,String[] p,int[] grants){super.onRequestPermissionsResult(req,p,grants);if(req==1&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)start();else new AlertDialog.Builder(this).setMessage("Per scansionare serve il permesso fotocamera. Puoi comunque aggiungere medicinali cercandoli per nome.").setPositiveButton("OK",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
 private void start(){ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{if(isFinishing()||isDestroyed())return;provider=future.get();Preview preview=new Preview.Builder().build();preview.setSurfaceProvider(view.getSurfaceProvider());ImageAnalysis analysis=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();analysis.setAnalyzer(executor,proxy->{if(finished||!busy.compareAndSet(false,true)){proxy.close();return;}android.media.Image image=proxy.getImage();if(image==null){busy.set(false);proxy.close();return;}try{InputImage input=InputImage.fromMediaImage(image,proxy.getImageInfo().getRotationDegrees());scanner.process(input).addOnSuccessListener(codes->{if(!finished)for(com.google.mlkit.vision.barcode.common.Barcode code:codes){String s=code.getRawValue();if(s!=null&&!s.isEmpty()){finished=true;setResult(RESULT_OK,new Intent().putExtra("code",s));finish();break;}}}).addOnCompleteListener(task->{proxy.close();busy.set(false);});}catch(Exception e){proxy.close();busy.set(false);}});provider.unbindAll();camera=provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,preview,analysis);}catch(Exception e){new AlertDialog.Builder(this).setTitle("Fotocamera non disponibile").setMessage("Usa la ricerca manuale per nome.\n"+e.getMessage()).setPositiveButton("OK",(d,w)->finish()).show();}},command->new Handler(Looper.getMainLooper()).post(command));}
 @Override public void onDestroy(){finished=true;if(provider!=null)provider.unbindAll();executor.shutdown();if(scanner!=null)scanner.close();super.onDestroy();}
}
